const parseList = (value, fallback) => {
    if (value === undefined || value === null || value === '') return fallback;
    try {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed)) return parsed.map((item) => String(item));
    } catch (_) {
        // ignore
    }
    return fallback;
};

if (msg.authRejected) {
    return [null, msg];
}
if (String(msg._authMode || 'enforce').toLowerCase() === 'off') {
    return [msg, null];
}

const requiredRoles = parseList(env.get('AI_INSIGHT_POLICY__REQUIRED_ROLES'), ['ai_insight_consumer']);
const roles = (msg.identity && Array.isArray(msg.identity.roles)) ? msg.identity.roles : [];
const missingRole = requiredRoles.find((role) => !roles.includes(role));
if (missingRole) {
    msg.statusCode = 403;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = { detail: 'Policy denied: missing required role ' + missingRole };
    return [null, msg];
}
return [msg, null];

const INSIGHT_TYPES = ['energy-summary', 'anomaly-report', 'city-status'];
const latestStore = global.get('aiInsightLatestOutputs') || {};
const now = new Date().toISOString();

const sanitizeOutput = (insightType, storedOutput) => {
    const output = (storedOutput && typeof storedOutput === 'object') ? storedOutput : {};
    const metadata = (output.metadata && typeof output.metadata === 'object') ? output.metadata : {};
    const llmModel = String(metadata.llm_model || 'rule-based-fallback');
    return {
        insight_type: insightType,
        summary: String(output.summary || ''),
        key_findings: Array.isArray(output.key_findings) ? output.key_findings.map((v) => String(v)) : [],
        recommendations: Array.isArray(output.recommendations) ? output.recommendations.map((v) => String(v)) : [],
        metadata: {
            output_id: String(metadata.output_id || `latest-${insightType}`),
            llm_model: llmModel,
            timestamp: String(metadata.timestamp || now),
            llm_used: llmModel !== 'rule-based-fallback',
            agreement_id: String(metadata.agreement_id || 'unknown-agreement'),
            asset_id: String(metadata.asset_id || 'unknown-asset'),
            llm_error: null,
        },
        data: output.data === undefined ? null : output.data,
    };
};

const latest = {};
for (const insightType of INSIGHT_TYPES) {
    const entry = latestStore[insightType];
    if (!entry || typeof entry !== 'object') {
        latest[insightType] = null;
        continue;
    }
    latest[insightType] = {
        cached_at: String(entry.cached_at || now),
        output: sanitizeOutput(insightType, entry.output),
    };
}

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { latest };
return [msg, null];

if (!msg.res) {
    return null;
}

const alreadySent = !!(msg.res.headersSent || (msg.res._res && (msg.res._res.headersSent || msg.res._res.writableEnded)));
if (alreadySent) {
    return null;
}

msg.statusCode = 500;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { detail: 'internal_error' };
return msg;
